<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_core_restricted( $user_id, $type = '' ) { global $wpdb; $t = sd_core_table_names(); $where = $type ? $wpdb->prepare( ' AND restriction_type=%s', sanitize_key( $type ) ) : ''; return (bool) $wpdb->get_var( $wpdb->prepare( "SELECT id FROM {$t['restrictions']} WHERE user_id=%d AND active=1 AND (expires_at IS NULL OR expires_at > %s) {$where} LIMIT 1", absint( $user_id ), current_time( 'mysql', true ) ) ); }
function sd_core_restrict_user( $user_id, $type, $reason, $expires_at = null ) { if ( ! sd_core_can_moderate( 'sd_manage_member_restrictions' ) || absint( $user_id ) === get_current_user_id() || user_can( $user_id, 'manage_options' ) ) { return new WP_Error( 'forbidden', __( 'This account cannot be restricted by your role.', 'social-discovery-core' ), array( 'status' => 403 ) ); } global $wpdb; $t = sd_core_table_names(); $wpdb->insert( $t['restrictions'], array( 'user_id' => absint( $user_id ), 'restriction_type' => sanitize_key( $type ), 'reason' => sanitize_textarea_field( $reason ), 'applied_by' => get_current_user_id(), 'starts_at' => current_time( 'mysql', true ), 'expires_at' => $expires_at ? gmdate( 'Y-m-d H:i:s', strtotime( $expires_at ) ) : null, 'active' => 1 ), array( '%d', '%s', '%s', '%d', '%s', '%s', '%d' ) ); sd_core_audit( 'restriction_applied', 'user', $user_id, 'success', $reason ); return $wpdb->insert_id; }
